// The finding closes here, the Vitre task closes there (26/09).
//
// op=close takes the appointment id that "send to handling" left in the
// finding's note ("Vitre SMS #N"), finds the task that appointment generated
// (get-review-result.actionId confirmed by /task/get/{id}, else a page scan
// of /task/get, which has no filter) and PUTs /task/close. Only a task Vitre
// says was generated by THAT appointment is ever closed.
//
// Server: the real module with fetch mocked. Client: the helpers cut out of
// index.html, run with a fake fetch, plus the wiring into the two manager
// flows (mark closed, verify a trustee's closure).
import { onRequest } from './_build/vitre.mjs';
import fs from 'node:fs';
let pass = 0, fail = 0;
const check = (l, c, d) => { if (c) { pass++; console.log('  ✓ ' + l); } else { fail++; console.log('  ✗ ' + l + (d !== undefined ? '  -> ' + JSON.stringify(d) : '')); } };
const SB = 'https://znhjtpcltrxxyfjczgvw.supabase.co';
const BASE = { VITRE_API_KEY_ID: 'kid', VITRE_API_KEY_SECRET: 'ksecret', SUPABASE_SERVICE_ROLE_KEY: 'srv', VITRE_NOTIFY_ENABLED: '1' };
const APPT = 3609174, TASK = 3364744;

// o.actionId      what get-review-result answers as actionId (null = none, 'err' = 500)
// o.detailGenBy   generatedByAppointmentId that /task/get/{id} reports (default APPT)
// o.detailNested  /task/get/{id} answers { task: {...} } instead of the row itself
// o.pages         array of arrays for /task/get?PageNumber=N (default: none)
// o.closed        the task already has a closeDate
// o.closeStatus   what PUT /task/close answers (default 200 { success:true })
// o.closeBody     raw body of that answer
function world(o) {
  o = o || {};
  const w = { calls: [], email: o.email === undefined ? 'manager@tfugen.local' : o.email };
  const task = { id: TASK, title: 'התראה מ-Tapugan Safety', generatedByAppointmentId: o.detailGenBy === undefined ? APPT : o.detailGenBy, closeDate: o.closed ? '2026-09-25T10:00:00' : null };
  globalThis.fetch = async (url, init) => {
    const u = String(url); const method = (init && init.method) || 'GET';
    w.calls.push({ u, method, body: init && init.body ? JSON.parse(init.body) : null, headers: (init && init.headers) || {} });
    const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json' } });
    if (u.startsWith(SB + '/auth/v1/user')) return json(w.email ? { id: 'u1', email: w.email, is_anonymous: false } : { id: 'a', is_anonymous: true });
    if (u.startsWith(SB + '/rest/v1/app_users')) return json(/manager|admin/.test(u) ? [{ role: /admin/.test(u) ? 'אדמין' : 'מנהל', active: true }] : [{ role: 'מדווח', active: true }]);
    if (u.includes('/appointmetResult/get-review-result/')) {
      if (o.actionId === 'err') return json({ message: 'boom' }, 500);
      return json({ appointmentId: APPT, actionId: o.actionId === undefined ? TASK : o.actionId, reviewName: 'x' });
    }
    if (/\/task\/get\/\d+$/.test(u)) return json(o.detailNested ? { task, events: [] } : task);
    if (u.includes('/task/get?')) {
      const page = parseInt(u.split('PageNumber=')[1], 10);
      const rows = (o.pages || [])[page - 1];
      return json(rows || []);
    }
    if (u.includes('/task/close')) {
      const st = o.closeStatus || 200;
      return new Response(o.closeBody !== undefined ? o.closeBody : JSON.stringify(st === 200 ? { success: true } : { message: 'task not found' }), { status: st, headers: { 'Content-Type': 'application/json' } });
    }
    return json({ message: 'unexpected ' + u }, 404);
  };
  return w;
}
const run = async (method, body, env) => {
  const r = await onRequest({ request: new Request('https://tapugan-safety.pages.dev/api/vitre?op=close', {
    method, headers: { origin: 'https://tapugan-safety.pages.dev', authorization: 'Bearer tok', 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body) }), env: env || BASE });
  let j = null; try { j = await r.json(); } catch (e) {}
  return { status: r.status, json: j };
};
const closes = (w) => w.calls.filter(c => c.u.includes('/task/close'));
const vitre = (w) => w.calls.filter(c => c.u.includes('hbinov'));
const OK = { appointmentId: APPT, description: 'נסגר ב-Tapugan Safety' };

console.log('\n1. gates');
{
  let w = world({ email: 'yos@tfugen.local' });
  let r = await run('POST', OK);
  check('a reporter is refused, Vitre never asked', r.status === 403 && vitre(w).length === 0, r);
  w = world({ email: null });
  r = await run('POST', OK);
  check('anonymous refused', r.status === 403 || r.status === 401, r);
  w = world();
  r = await run('POST', OK, Object.assign({}, BASE, { VITRE_NOTIFY_ENABLED: '' }));
  check('channel paused: close refused too (the channel that opens tasks is the one that closes them)', r.status === 403 && /paused/.test(r.json.error) && vitre(w).length === 0, r);
  r = await run('GET', undefined);
  check('GET refused (405)', r.status === 405, r);
  for (const bad of [{}, { appointmentId: 'abc' }, { appointmentId: '12abc' }, { appointmentId: -5 }, { appointmentId: 0 }, { appointmentId: '3609174; DROP' }]) {
    w = world();
    r = await run('POST', bad);
    check('bad appointmentId -> 400: ' + JSON.stringify(bad), r.status === 400 && vitre(w).length === 0, r);
  }
}

console.log('\n2. the happy path: actionId confirmed by the task detail, then PUT /task/close');
{
  const w = world();
  const r = await run('POST', OK);
  check('200 ok with the task id', r.status === 200 && r.json.ok && r.json.taskId === TASK && r.json.alreadyClosed === false && r.json.appointmentId === APPT, r.json);
  const seq = vitre(w).map(c => c.method + ' ' + c.u.replace('https://publicapi.hbinov.com', ''));
  check('get-review-result, then /task/get/{id}, then PUT /task/close, nothing else', seq.join(' | ') === 'GET /appointmetResult/get-review-result/' + APPT + ' | GET /task/get/' + TASK + ' | PUT /task/close', seq);
  const c = closes(w)[0];
  check('TaskCloseModel: taskId, isHandled:true, taskHandled.description', JSON.stringify(c.body) === JSON.stringify({ taskId: TASK, isHandled: true, taskHandled: { description: 'נסגר ב-Tapugan Safety' } }), c.body);
  check('with the Vitre keys', c.headers['X-api-key-id'] === 'kid' && c.headers['X-api-key-secret'] === 'ksecret');
  check('no page scan was needed', !w.calls.some(x => x.u.includes('/task/get?')));
  const w2 = world({ detailNested: true });
  const r2 = await run('POST', OK);
  check('a detail wrapped as { task: {...} } is read too', r2.status === 200 && r2.json.taskId === TASK && closes(w2).length === 1, r2.json);
  const w3 = world();
  const r3 = await run('POST', { appointmentId: String(APPT), description: '' });
  check('appointmentId as a digit string is accepted; empty description gets a default', r3.status === 200 && closes(w3)[0].body.taskHandled.description === 'Closed in Tapugan Safety', closes(w3)[0] && closes(w3)[0].body);
  const w4 = world();
  await run('POST', { appointmentId: APPT, description: 'x'.repeat(2000) });
  check('description capped at 1000', closes(w4)[0].body.taskHandled.description.length === 1000);
}

console.log('\n3. only a task generated by THIS appointment is closed');
{
  // actionId points at a task generated by another appointment: the scan finds the right one.
  let w = world({ detailGenBy: 111, pages: [Array.from({ length: 200 }, (_, i) => ({ id: i + 1, generatedByAppointmentId: 5 })), [{ id: 500, generatedByAppointmentId: 6 }, { id: TASK + 1, generatedByAppointmentId: APPT, closeDate: null }]] });
  let r = await run('POST', OK);
  check('actionId mismatch -> page scan -> the matching task', r.status === 200 && r.json.taskId === TASK + 1 && closes(w)[0].body.taskId === TASK + 1, r.json);
  check('the mismatching task was NOT closed', !closes(w).some(c => c.body.taskId === TASK));
  check('scan stopped at the short page', w.calls.filter(c => c.u.includes('/task/get?')).length === 2);
  w = world({ actionId: null, pages: [[{ id: 9, generatedByAppointmentId: APPT }]] });
  r = await run('POST', OK);
  check('no actionId at all -> scan finds it on page 1', r.status === 200 && r.json.taskId === 9, r.json);
  w = world({ actionId: 'err', pages: [[{ id: 9, generatedByAppointmentId: APPT }]] });
  r = await run('POST', OK);
  check('get-review-result 500 is not fatal: the scan still runs', r.status === 200 && r.json.taskId === 9, r.json);
  w = world({ actionId: null, pages: [[{ id: 1, generatedByAppointmentId: 5 }]] });
  r = await run('POST', OK);
  check('nothing generated by the appointment -> 404, nothing closed', r.status === 404 && /no Vitre task/.test(r.json.error) && closes(w).length === 0 && Array.isArray(r.json.lookup), r.json);
  w = world({ actionId: null, pages: Array.from({ length: 45 }, () => Array.from({ length: 200 }, (_, i) => ({ id: i, generatedByAppointmentId: 5 }))) });
  r = await run('POST', OK);
  check('the scan gives up after 40 pages', r.status === 404 && w.calls.filter(c => c.u.includes('/task/get?')).length === 40, w.calls.filter(c => c.u.includes('/task/get?')).length);
}

console.log('\n4. already closed, Vitre errors');
{
  let w = world({ closed: true });
  let r = await run('POST', OK);
  check('a task with closeDate is left alone: ok + alreadyClosed, no PUT', r.status === 200 && r.json.alreadyClosed === true && r.json.taskId === TASK && closes(w).length === 0, r.json);
  w = world({ closeStatus: 404 });
  r = await run('POST', OK);
  check('Vitre 404 on close -> 502 with the message', r.status === 502 && /404/.test(r.json.error) && r.json.detail === 'task not found' && r.json.taskId === TASK, r.json);
  w = world({ closeBody: JSON.stringify({ success: false }) });
  r = await run('POST', OK);
  check('200 with success:false is not a close', r.status === 502 && /confirm/.test(r.json.error), r.json);
  check('the keys are never in a response', !JSON.stringify(r.json).includes('ksecret'));
}

console.log('\n5. client: note parsing, the call, the note afterwards (index.html)');
{
  const html = fs.readFileSync(new URL('../../index.html', import.meta.url), 'utf8');
  const from = html.indexOf('function _truVitreApptOf'), to = html.indexOf('function _truMgrSetStatus');
  const src = html.slice(from, to);
  check('helpers found in index.html', from > 0 && to > from);
  const mk = (fetchImpl, user) => {
    const log = { upd: [], toasts: [], sdb: 0 };
    const ctx = {
      fetch: fetchImpl, toast: (m) => log.toasts.push(m), sbUpd: (t, r) => log.upd.push({ t, r: Object.assign({}, r) }), sdb: () => log.sdb++,
      rTrustees: () => {}, _sbToken: 'tok', _currentUser: user === undefined ? { username: 'michael' } : user, _VITRE_SMS_ON: true,
      fd: (d) => { const p = String(d).split('-'); return p[2] + '/' + p[1] + '/' + p[0]; }
    };
    const fn = new Function(...Object.keys(ctx), src + '\nreturn { apptOf: _truVitreApptOf, closedIn: _truVitreClosedIn, close: _truVitreClose };');
    return { api: fn(...Object.values(ctx)), log };
  };
  const NOTE = 'נותב לאחזקה עד 03/10/2026 (Vitre SMS #3609174 26/09/2026)';
  const { api } = mk(async () => { throw new Error('no'); });
  check('the appointment id is read from the note', api.apptOf({ mgr_note: NOTE }) === '3609174');
  check('a note without it -> null', api.apptOf({ mgr_note: 'נותב ידנית' }) === null && api.apptOf({}) === null);
  check('WhatsApp routing note has no appointment', api.apptOf({ mgr_note: 'נותב לדני (WhatsApp 26/09/2026)' }) === null);
  check('closedIn detects the closed marker', api.closedIn({ mgr_note: NOTE + ' · Vitre משימה #3364744 נסגרה' }) === true && api.closedIn({ mgr_note: NOTE }) === false);

  // the call
  let calls = [];
  const fetchOk = async (u, init) => { calls.push({ u, body: JSON.parse(init.body), headers: init.headers }); return { ok: true, status: 200, json: async () => ({ ok: true, taskId: 3364744, alreadyClosed: false }) }; };
  let m = mk(fetchOk);
  let r = { id: 'x', mgr_note: NOTE, s: 'נסגר' };
  let res = await m.api.close(r);
  check('POST /api/vitre?op=close with the appointment id and a description naming the user', res === true && calls.length === 1 && calls[0].u === '/api/vitre?op=close' && calls[0].body.appointmentId === '3609174' && /michael/.test(calls[0].body.description) && calls[0].headers.Authorization === 'Bearer tok', calls[0]);
  check('the note now carries the task number as closed, and was saved', /Vitre משימה #3364744 נסגרה$/.test(r.mgr_note) && m.log.upd.length === 1 && m.log.upd[0].t === 'trustee_reports' && m.log.sdb === 1, { note: r.mgr_note, upd: m.log.upd.length });
  check('a success toast', m.log.toasts.some(t => /#3364744/.test(t)), m.log.toasts);
  res = await m.api.close(r);
  check('a second close is a no-op (marker in the note)', res === null && calls.length === 1);

  calls = [];
  m = mk(fetchOk);
  res = await m.api.close({ mgr_note: 'נותב ידנית' });
  check('no appointment in the note -> nothing is called', res === null && calls.length === 0);
  m = mk(fetchOk);
  const ctxOff = mk(fetchOk);
  // the page flag off: nothing goes out
  const fnOff = new Function('fetch', 'toast', 'sbUpd', 'sdb', 'rTrustees', '_sbToken', '_currentUser', '_VITRE_SMS_ON', 'fd', src + '\nreturn _truVitreClose;')(fetchOk, () => {}, () => {}, () => {}, () => {}, 'tok', { username: 'm' }, false, (d) => d);
  check('_VITRE_SMS_ON=false: nothing is called', fnOff({ mgr_note: NOTE }) === null && calls.length === 0);
  void ctxOff;

  // failure: the local close is not undone, the note is untouched, a toast says so
  const fetchFail = async () => ({ ok: false, status: 502, json: async () => ({ error: 'vitre 404', detail: 'task not found' }) });
  m = mk(fetchFail);
  r = { mgr_note: NOTE };
  res = await m.api.close(r);
  check('Vitre failure: false, note untouched, nothing saved, a warning toast with the detail', res === false && r.mgr_note === NOTE && m.log.upd.length === 0 && m.log.toasts.some(t => /task not found/.test(t)), { note: r.mgr_note, toasts: m.log.toasts });
  const fetchThrow = async () => { throw new Error('offline'); };
  m = mk(fetchThrow);
  res = await m.api.close({ mgr_note: NOTE });
  check('network error: false + toast, no throw', res === false && m.log.toasts.some(t => /offline/.test(t)), m.log.toasts);
  const fetchAlready = async () => ({ ok: true, status: 200, json: async () => ({ ok: true, taskId: 7, alreadyClosed: true }) });
  m = mk(fetchAlready);
  r = { mgr_note: NOTE };
  res = await m.api.close(r);
  check('already closed in Vitre: marker written, toast says so', res === true && /#7 נסגרה/.test(r.mgr_note) && m.log.toasts.some(t => /כבר/.test(t)), { note: r.mgr_note, toasts: m.log.toasts });

  // wiring into the two manager flows
  const setStatus = html.slice(html.indexOf('function _truMgrSetStatus'), html.indexOf('function _truMgrSetStatus') + 400);
  check('_truMgrSetStatus closes in Vitre when the new status is נסגר, after the local save', /sbUpd\('trustee_reports',r\);sdb\(\);\n  if\(st===TRUSTEE_S_CLOSED\)_truVitreClose\(r\);/.test(setStatus));
  const verify = html.slice(html.indexOf('window._truVerifyClose=function'), html.indexOf('function _truVerifyBadge'));
  check('_truVerifyClose closes in Vitre after saving the verification', /r\.verified_at=new Date\(\)\.toISOString\(\);\n  sbUpd\('trustee_reports',r\);sdb\(\);\n  _truVitreClose\(r\);/.test(verify));
  check('no raw Hebrew in the new client code', !/[֐-׿]/.test(src));
}

console.log('\n' + pass + ' passed, ' + fail + ' failed');
process.exit(fail ? 1 : 0);
